=== wrong_baud.ino ===
   1| /*
   2|  * Lab 5: answer ID?/SUM?/HEX? on Serial1
   3|  *
   4|  * ID: <student_id>
   5|  * SUM computed at runtime from the digits.
   6|  * HEX printed with Serial's HEX formatter (upper case).
   7|  */
   8| 
   9| const char myId[] = "<student_id>";
  10| String inLine;
  11| 
  12| int computeSum() {
  13|   int s = 0;
  14|   for (const char *p = myId; *p; ++p) s += (*p - '0');
  15|   return s;
  16| }
  17| 
  18| void answer(const String &c) {
  19|   if (c == "ID?")       Serial1.println(myId);
  20|   else if (c == "SUM?") Serial1.println(computeSum());
  21|   else if (c == "HEX?") Serial1.println(strtoul(myId, 0, 10), HEX);
  22|   else                  Serial1.println("ERR");
  23| }
  24| 
  25| void setup() {
  26|   Serial1.begin(115200);
  27|   inLine.reserve(16);
  28| }
  29| 
  30| void loop() {
  31|   while (Serial1.available()) {
  32|     char c = Serial1.read();
  33|     if (c == '\r') continue;          // ignore CR from CRLF endings
  34|     if (c == '\n') {
  35|       if (inLine.length()) answer(inLine);
  36|       inLine = "";
  37|     } else {
  38|       inLine += c;
  39|     }
  40|   }
  41| }
</student_code>
